 64	
 65	        const ts1 = resultEvent.getTs();
 66	        const ret = [<DateSeparator key={ts1 + "-search"} roomId={resultEvent.getRoomId()} ts={ts1} />];
 67	        const layout = SettingsStore.getValue("layout");
 68	        const isTwelveHour = SettingsStore.getValue("showTwelveHourTimestamps");
 69	        const alwaysShowTimestamps = SettingsStore.getValue("alwaysShowTimestamps");
 70	        const threadsEnabled = SettingsStore.getValue("feature_threadstable");
 71	
 72	        const timeline = result.context.getTimeline();
 73	        for (let j = 0; j < timeline.length; j++) {
 74	            const mxEv = timeline[j];
 75	            let highlights;
 76	            const contextual = j != result.context.getOurEventIndex();
 77	            if (!contextual) {
 78	                highlights = this.props.searchHighlights;
 79	            }
 80	
 81	            if (haveRendererForEvent(mxEv, this.context?.showHiddenEvents)) {
 82	                // do we need a date separator since the last event?
 83	                const prevEv = timeline[j - 1];
 84	                // is this a continuation of the previous message?
 85	                const continuation =
 86	                    prevEv &&
 87	                    !wantsDateSeparator(prevEv.getDate(), mxEv.getDate()) &&
 88	                    shouldFormContinuation(
 89	                        prevEv,
 90	                        mxEv,
 91	                        this.context?.showHiddenEvents,
 92	                        threadsEnabled,
 93	                        TimelineRenderingType.Search,
 94	                    );
 95	
 96	                let lastInSection = true;
 97	                const nextEv = timeline[j + 1];
 98	                if (nextEv) {
 99	                    const willWantDateSeparator = wantsDateSeparator(mxEv.getDate(), nextEv.getDate());
100	                    lastInSection =
101	                        willWantDateSeparator ||
102	                        mxEv.getSender() !== nextEv.getSender() ||
103	                        !shouldFormContinuation(
104	                            mxEv,
105	                            nextEv,
106	                            this.context?.showHiddenEvents,
107	                            threadsEnabled,
108	                            TimelineRenderingType.Search,
109	                        );
110	                }
111	
112	                ret.push(
113	                    <EventTile
114	                        key={`${eventId}+${j}`}
115	                        mxEvent={mxEv}
116	                        layout={layout}
117	                        contextual={contextual}
118	                        highlights={highlights}
119	                        permalinkCreator={this.props.permalinkCreator}
120	                        highlightLink={this.props.resultLink}
121	                        onHeightChanged={this.props.onHeightChanged}
122	                        isTwelveHour={isTwelveHour}
123	                        alwaysShowTimestamps={alwaysShowTimestamps}
124	                        lastInSection={lastInSection}
125	                        continuation={continuation}
