import { MatrixEvent } from "matrix-js-sdk/src/models/event";
import { THREAD_RELATION_TYPE } from "matrix-js-sdk/src/models/thread";
import { logger } from "matrix-js-sdk/src/logger";

import ScrollPanel from "./ScrollPanel";
import { SearchScope } from "../views/rooms/SearchBar";
import Spinner from "../views/elements/Spinner";
import { _t } from "../../languageHandler";
import { haveRendererForEvent } from "../../events/EventTileFactory";
import SearchResultTile from "../views/rooms/SearchResultTile";
import { searchPagination } from "../../Searching";
import Modal from "../../Modal";
import ErrorDialog from "../views/dialogs/ErrorDialog";
import ResizeNotifier from "../../utils/ResizeNotifier";
import MatrixClientContext from "../../contexts/MatrixClientContext";
import { RoomPermalinkCreator } from "../../utils/permalinks/Permalinks";
import RoomContext from "../../contexts/RoomContext";
import SettingsStore from "../../settings/SettingsStore";

const DEBUG = false;
let debuglog = function (msg: string) {};

/* istanbul ignore next */
if (DEBUG) {
    // using bind means that we get to keep useful line numbers in the console
    debuglog = logger.log.bind(console);
}

interface Props {
    term: string;
    scope: SearchScope;
    promise: Promise<ISearchResults>;
    abortController?: AbortController;
    resizeNotifier: ResizeNotifier;
    permalinkCreator: RoomPermalinkCreator;
    className: string;
    onUpdate(inProgress: boolean, results: ISearchResults | null): void;
}

// XXX: why doesn't searching on name work?
export const RoomSearchView = forwardRef<ScrollPanel, Props>(
    (
        { term, scope, promise, abortController, resizeNotifier, permalinkCreator, className, onUpdate }: Props,
        ref: RefObject<ScrollPanel>,
    ) => {
        const client = useContext(MatrixClientContext);
        const roomContext = useContext(RoomContext);
        const [inProgress, setInProgress] = useState(true);
        const [highlights, setHighlights] = useState<string[] | null>(null);
        const [results, setResults] = useState<ISearchResults | null>(null);
        const aborted = useRef(false);

        const handleSearchResult = useCallback(
            (searchPromise: Promise<ISearchResults>): Promise<boolean> => {
                setInProgress(true);

                return searchPromise
                    .then(
                        async (results) => {
                            debuglog("search complete");
                            if (aborted.current) {
                                logger.error("Discarding stale search results");
                                return false;
                            }

                            // postgres on synapse returns us precise details of the strings
                            // which actually got matched for highlighting.
                            //
                            // In either case, we want to highlight the literal search term
                            // whether it was used by the search engine or not.

                            let highlights = results.highlights;
                            if (!highlights.includes(term)) {
                                highlights = highlights.concat(term);
                            }

                            // For overlapping highlights,
                            // favour longer (more specific) terms first
                            highlights = highlights.sort(function (a, b) {
                                return b.length - a.length;
                            });

                            if (SettingsStore.getValue("feature_threadstable")) {
                                // Process all thread roots returned in this batch of search results
                                // XXX: This won't work for results coming from Seshat which won't include the bundled relationship
                                for (const result of results.results) {
                                    for (const event of result.context.getTimeline()) {
                                        const bundledRelationship =
                                            event.getServerAggregatedRelation<IThreadBundledRelationship>(
                                                THREAD_RELATION_TYPE.name,
                                            );
                                        if (!bundledRelationship || event.getThread()) continue;
                                        const room = client.getRoom(event.getRoomId());
                                        const thread = room.findThreadForEvent(event);
                                        if (thread) {
                                            event.setThread(thread);
                                        } else {
                                            room.createThread(event.getId(), event, [], true);
                                        }
                                    }
                                }
                            }

                            setHighlights(highlights);
                            setResults({ ...results }); // copy to force a refresh
                        },
                        (error) => {
                            if (aborted.current) {
                                logger.error("Discarding stale search results");
                                return false;
                            }

        let lastRoomId: string;
        let mergedTimeline: MatrixEvent[] | null = null;
        let ourEventsIndexes: number[] = [];
        let mergedResultEvent: MatrixEvent | null = null;
        let mergedRoomName: string | undefined;
        let hasDirectMatch = false;

        const renderMergedResult = (): void => {
            if (!mergedTimeline || !mergedResultEvent) return;

            const roomId = mergedResultEvent.getRoomId();
            if (scope === SearchScope.All && roomId !== lastRoomId) {
                ret.push(
                    <li key={mergedResultEvent.getId() + "-room"}>
                        <h2>
                            {_t("Room")}: {mergedRoomName}
                        </h2>
                    </li>,
                );
                lastRoomId = roomId;
            }

            const matchIds = ourEventsIndexes.map((index) => mergedTimeline![index].getId());
            ret.push(
                <SearchResultTile
                    key={matchIds.join(",") || mergedResultEvent.getId()}
                    timeline={mergedTimeline}
                    ourEventsIndexes={ourEventsIndexes}
                    searchHighlights={highlights}
                    permalinkCreator={permalinkCreator}
                    onHeightChanged={onHeightChanged}
                />,
            );

            mergedTimeline = null;
            ourEventsIndexes = [];
            mergedResultEvent = null;
            mergedRoomName = undefined;
            hasDirectMatch = false;
        };

        for (let i = (results?.results?.length || 0) - 1; i >= 0; i--) {
            const result = results.results[i];

            const mxEv = result.context.getEvent();
            const roomId = mxEv.getRoomId();
            const room = client.getRoom(roomId);
            if (!room) {
                // if we do not have the room in js-sdk stores then hide it as we cannot easily show it
                // As per the spec, an all rooms search can create this condition,
                // it happens with Seshat but not Synapse.
                // It will make the result count not match the displayed count.
                logger.log("Hiding search result from an unknown room", roomId);
                renderMergedResult();
                continue;
            }

            if (!haveRendererForEvent(mxEv, roomContext.showHiddenEvents)) {
                // XXX: can this ever happen? It will make the result count
                // not match the displayed count.
                renderMergedResult();
                continue;
            }

            const timeline = result.context.getTimeline();
            const nextOurEventIndex = result.context.getOurEventIndex();
            const nextHasDirectMatch = nextOurEventIndex >= 0 && nextOurEventIndex < timeline.length;
            const overlaps =
                mergedTimeline !== null &&
                hasDirectMatch &&
                nextHasDirectMatch &&
                mergedTimeline[mergedTimeline.length - 1]?.getId() === timeline[0]?.getId();

            if (overlaps) {
                const offset = mergedTimeline.length;
                ourEventsIndexes.push(offset + (nextOurEventIndex - 1));
                mergedTimeline.push(...timeline.slice(1));
                hasDirectMatch = nextHasDirectMatch;
                continue;
            }

            renderMergedResult();
            mergedTimeline = [...timeline];
            ourEventsIndexes = nextHasDirectMatch ? [nextOurEventIndex] : [];
            mergedResultEvent = mxEv;
            mergedRoomName = room.name;
            hasDirectMatch = nextHasDirectMatch;
        }

        renderMergedResult();

        return (
            <ScrollPanel
                ref={ref}
                className={"mx_RoomView_searchResultsPanel " + className}
                onFillRequest={onSearchResultsFillRequest}
                resizeNotifier={resizeNotifier}
            >
                <li className="mx_RoomView_scrollheader" />
                {ret}
            </ScrollPanel>
        );
    },
);

            }
