        let lastRoomId: string;
        let mergedTimeline: MatrixEvent[] | null = null;
        let ourEventsIndexes: number[] = [];
        let mergedResultEvent: MatrixEvent | null = null;
        let mergedRoomName: string | undefined;
        let hasDirectMatch = false;

        const renderMergedResult = (): void => {
            if (!mergedTimeline || !mergedResultEvent) return;

            const roomId = mergedResultEvent.getRoomId();
            if (scope === SearchScope.All && roomId !== lastRoomId) {
                ret.push(
                    <li key={mergedResultEvent.getId() + "-room"}>
                        <h2>
                            {_t("Room")}: {mergedRoomName}
                        </h2>
                    </li>,
                );
                lastRoomId = roomId;
            }

            const matchIds = ourEventsIndexes.map((index) => mergedTimeline![index].getId());
            ret.push(
                <SearchResultTile
                    key={matchIds.join(",") || mergedResultEvent.getId()}
                    timeline={mergedTimeline}
                    ourEventsIndexes={ourEventsIndexes}
                    searchHighlights={highlights}
                    permalinkCreator={permalinkCreator}
                    onHeightChanged={onHeightChanged}
                />,
